// Extract event data and prepare for processing
const input = $input.first().json;

// Get raw body for signature verification
const rawBody = input.rawBody || '';
const headers = input.headers || {};
const stripeSignature = headers['stripe-signature'] || '';

if (!stripeSignature) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Missing Stripe signature header',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Parse the event body
let event;
try {
  event = typeof input.body === 'string' ? JSON.parse(input.body) : input.body;
} catch (e) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Invalid JSON payload',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

if (!event || !event.type) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Invalid Stripe event format',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Extract project_id from various locations
let project_id = null;
let metadata = {};

const eventObject = event.data?.object || {};

// Try different locations for metadata
if (eventObject.metadata?.project_id) {
  metadata = eventObject.metadata;
  project_id = metadata.project_id;
} else if (eventObject.subscription_details?.metadata?.project_id) {
  metadata = eventObject.subscription_details.metadata;
  project_id = metadata.project_id;
} else if (eventObject.lines?.data?.[0]?.metadata?.project_id) {
  metadata = eventObject.lines.data[0].metadata;
  project_id = metadata.project_id;
}

if (!project_id) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'No project_id found in event metadata',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: project_id,
    metadata: metadata,
    event: event,
    eventType: event.type,
    eventId: event.id,
    eventObject: eventObject,
    rawBody: rawBody,
    stripeSignature: stripeSignature
  }
}];

// Verify Stripe signature
const crypto = require('crypto');

const dbResults = $('Get Webhook Secret').all();
const inputData = $('Parse Webhook').first().json;

if (!dbResults || dbResults.length === 0 || !dbResults[0].json.webhook_secret) {
  return [{
    json: {
      verified: false,
      error: {
        code: 400,
        message: `Project '${inputData.project_id}' not found or no webhook secret configured`,
        status: 'BAD_REQUEST'
      }
    }
  }];
}

const webhookSecret = dbResults[0].json.webhook_secret;
const payload = inputData.rawBody;
const sigHeader = inputData.stripeSignature;

// Parse the signature header
const sigParts = {};
sigHeader.split(',').forEach(part => {
  const [key, value] = part.split('=');
  if (key && value) {
    sigParts[key] = value;
  }
});

const timestamp = sigParts.t;
const signature = sigParts.v1;

if (!timestamp || !signature) {
  return [{
    json: {
      verified: false,
      error: {
        code: 400,
        message: 'Invalid Stripe signature format',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Check timestamp (allow 5 minutes tolerance)
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - parseInt(timestamp)) > 300) {
  return [{
    json: {
      verified: false,
      error: {
        code: 400,
        message: 'Webhook timestamp too old',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Compute expected signature
const signedPayload = `${timestamp}.${payload}`;
const expectedSig = crypto
  .createHmac('sha256', webhookSecret)
  .update(signedPayload)
  .digest('hex');

// Compare signatures
if (signature !== expectedSig) {
  return [{
    json: {
      verified: false,
      error: {
        code: 400,
        message: 'Invalid Stripe signature',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Signature verified!
return [{
  json: {
    verified: true,
    project_id: inputData.project_id,
    metadata: inputData.metadata,
    event: inputData.event,
    eventType: inputData.eventType,
    eventId: inputData.eventId,
    eventObject: inputData.eventObject
  }
}];

// Determine callback URL based on event type
const data = $input.first().json;
const eventType = data.eventType;
const metadata = data.metadata || {};

// Map event types to callback keys
const eventCallbackMap = {
  'checkout.session.completed': 'callback_success',
  'invoice.payment_succeeded': 'callback_renewal',
  'invoice.payment_failed': 'callback_failure',
  'customer.subscription.deleted': 'callback_cancel',
  'customer.subscription.updated': 'callback_success'
};

const callbackKey = eventCallbackMap[eventType];

if (!callbackKey) {
  // Event type not handled - acknowledge but don't process
  return [{
    json: {
      shouldRoute: false,
      reason: `Event type '${eventType}' not handled`,
      eventId: data.eventId
    }
  }];
}

const callbackUrl = metadata[callbackKey];

if (!callbackUrl) {
  // No callback configured for this event
  return [{
    json: {
      shouldRoute: false,
      reason: `No ${callbackKey} URL configured for project`,
      eventId: data.eventId
    }
  }];
}

// Prepare callback payload
const eventObject = data.eventObject;
const callbackPayload = {
  event_type: eventType,
  event_id: data.eventId,
  project_id: data.project_id,
  timestamp: new Date().toISOString(),
  data: {}
};

// Extract relevant data based on event type
switch (eventType) {
  case 'checkout.session.completed':
    callbackPayload.data = {
      customer_id: eventObject.customer,
      customer_email: eventObject.customer_email || eventObject.customer_details?.email,
      subscription_id: eventObject.subscription,
      payment_status: eventObject.payment_status,
      amount_total: eventObject.amount_total,
      currency: eventObject.currency,
      metadata: eventObject.metadata
    };
    break;

  case 'invoice.payment_succeeded':
  case 'invoice.payment_failed':
    callbackPayload.data = {
      customer_id: eventObject.customer,
      customer_email: eventObject.customer_email,
      subscription_id: eventObject.subscription,
      invoice_id: eventObject.id,
      amount_paid: eventObject.amount_paid,
      amount_due: eventObject.amount_due,
      currency: eventObject.currency,
      status: eventObject.status,
      billing_reason: eventObject.billing_reason,
      period_start: eventObject.period_start,
      period_end: eventObject.period_end
    };
    break;

  case 'customer.subscription.deleted':
  case 'customer.subscription.updated':
    callbackPayload.data = {
      customer_id: eventObject.customer,
      subscription_id: eventObject.id,
      status: eventObject.status,
      cancel_at: eventObject.cancel_at,
      canceled_at: eventObject.canceled_at,
      current_period_end: eventObject.current_period_end,
      plan_id: eventObject.items?.data?.[0]?.price?.id,
      metadata: eventObject.metadata
    };
    break;
}

return [{
  json: {
    shouldRoute: true,
    callbackUrl: callbackUrl,
    callbackPayload: callbackPayload,
    eventId: data.eventId,
    eventType: eventType
  }
}];

// Log callback result
const response = $input.first().json;
const prevData = $('Determine Callback').first().json;

const success = response.statusCode >= 200 && response.statusCode < 300;

return [{
  json: {
    received: true,
    event_id: prevData.eventId,
    event_type: prevData.eventType,
    callback_status: success ? 'delivered' : 'failed',
    callback_url: prevData.callbackUrl,
    callback_response_code: response.statusCode
  }
}];
